# checks.py: the trainer's helper. Students do NOT edit this file.
# It loads each step file, tests it, and tells final.py which steps are done.
import importlib, sys, traceback

try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass

APP = "Marks Analyzer"
TOTAL = 10
# (number, file, title, function name, day, test)
STEPS = [
    (1, 'step01_header', 'Page title', 'header', 2, lambda f: '<h1' in str(f())),
    (2, 'step02_name_box', 'Name input box', 'name_box', 2, lambda f: 'name="name"' in str(f())),
    (3, 'step03_marks_box', 'Marks input box', 'marks_box', 2, lambda f: 'name="marks"' in str(f())),
    (4, 'step04_add_button', 'Add button', 'add_button', 2, lambda f: '<button' in str(f())),
    (5, 'step05_show_list', 'Show each student in the list', 'student_row', 2, lambda f: 'Ravi' in str(f({'name':'Ravi','marks':90})) and '90' in str(f({'name':'Ravi','marks':90}))),
    (6, 'step06_total', 'Total marks', 'total_marks', 2, lambda f: f([{'name':'A','marks':50},{'name':'B','marks':70}]) == 120),
    (7, 'step07_grade', 'Grade with if / else', 'grade', 2, lambda f: f(95) == 'A' and f(80) == 'B' and f(65) == 'C' and f(30) == 'D'),
    (8, 'step08_topper', 'Find the topper', 'topper', 2, lambda f: (f([{'name':'A','marks':50},{'name':'B','marks':90},{'name':'C','marks':70}]) or {}).get('name') == 'B'),
    (9, 'step09_delete', 'Delete a student', 'delete_student', 2, lambda f: (lambda L: (f(L, 1), [x['name'] for x in L] == ['A', 'C'])[1])([{'name':'A','marks':1},{'name':'B','marks':2},{'name':'C','marks':3}])),
    (10, 'step10_footer', 'Footer with your name', 'footer', 2, lambda f: '<footer' in str(f())),
]


def load(n):
    """Return a dict: status is 'done', 'todo' or 'error'."""
    num, mod, title, fn, day, test = STEPS[n - 1]
    info = {"n": num, "title": title, "file": mod + ".py", "day": day, "f": None, "status": "todo", "err": ""}
    try:
        if mod in sys.modules:
            m = importlib.reload(sys.modules[mod])
        else:
            m = importlib.import_module(mod)
        f = getattr(m, fn)
        info["f"] = f
        info["status"] = "done" if test(f) else "todo"
    except Exception as e:
        info["status"] = "error"
        tb = traceback.extract_tb(e.__traceback__)
        line = ""
        for fr in tb:
            if fr.filename.endswith(mod + ".py"):
                line = " (line %d)" % fr.lineno
        if isinstance(e, SyntaxError):
            line = ""   # the message already has the line number
        info["err"] = "%s: %s%s" % (type(e).__name__, e, line)
    return info


def load_all():
    return {n: load(n) for n in range(1, TOTAL + 1)}


def run(n):
    s = load(n)
    print()
    if s["status"] == "done":
        print("  ✅  Step %d done: %s" % (n, s["title"]))
        print("      Refresh the browser page to see it. Then open step %02d." % (n + 1) if n < TOTAL else "      🎉 All steps finished!")
    elif s["status"] == "error":
        print("  🔴  Step %d has an error: %s" % (n, s["err"]))
        print("      Check spelling, quotes \" \", brackets ( ) and the spaces at the start of the line.")
    else:
        print("  ❌  Step %d not done yet: %s" % (n, s["title"]))
        print("      Open %s, type the line shown in the comment, save (Ctrl + S) and run this again." % s["file"])
    done = sum(1 for k in range(1, TOTAL + 1) if load(k)["status"] == "done")
    print("      Progress: %d / %d steps done" % (done, TOTAL))
    print()
